--!nonstrict
local slot = require("../components/slot")
local states = require("../../core/states")
local vide = require("../../../vide")

local apply = vide.apply
local cleanup = vide.cleanup
local effect = vide.effect
local source = vide.source

local controls = {
	name = "Tool",
	textureId = "",
	tooltip = "",
	keyboardHint = true,
}

type Props = {
	controls: typeof(controls),
}

return {
	vide = vide,
	controls = controls,
	story = function(props: Props)
		local item = Instance.new("Tool")
		cleanup(item)

		effect(function()
			item.Name = props.controls.name()
			item.TextureId = props.controls.textureId()
			item.ToolTip = props.controls.tooltip()
			states.keyboardHint(props.controls.keyboardHint())
		end)

		return apply(slot({
			item = source(item),
			order = 1,
			inHotbar = true,
		}))({
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
		})
	end,
}

local tooltip = require("../components/tooltip")
local vide = require("../../../vide")

local create = vide.create

return {
	vide = vide,
	story = function()
		return create("Frame")({
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),

			tooltip({
				text = function()
					return "Hello World"
				end,
			}),
		})
	end,
}
